def L(id, f, t, type, grade, conf, claim, objection, warrant, verdict, cross=False, tests=None, by="ai", red="pending", date="2026-10-28", editor=None):
    d = dict(id=id, f=f, t=t, type=type, grade=grade, conf=conf, cross=cross,
             note=dict(claim=claim, objection=objection, warrant=warrant, verdict=verdict),
             audit=dict(by=by, red=red, date=date))
    if tests: d["tests"] = tests
    if editor: d["audit"]["editor"] = editor
    return d

